   Brand: indigo (action, the current reader) and coral (an open item that still needs someone).
   Ground: white, the colour of the note itself. Fine rules do the grouping; no shadows. */
:root {
  --indigo: #3B3FD9;
  --indigo-ink: #2F32B5;
  --indigo-tint: #ECEDFB;
  --coral: #FF7A59;
  --coral-tint: #FFE9E2;

  --ink: #15161F;
  --ink-2: #4C4F5E;
  --ink-3: #6B6E7C;
  --rule: #D9DBE4;
  --rule-soft: #E9EAF0;
  --ground: #FFFFFF;
  --panel: #F4F5F9;

  --display: Charter, "Bitstream Charter", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --text: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, "DejaVu Sans Mono", monospace;

  --fs-body: 1.0625rem;              /* 17px */
  --fs-small: 0.9375rem;             /* 15px */
  --fs-meta: 0.8125rem;              /* 13px */
  --fs-h1: clamp(2.375rem, 1.55rem + 3.4vw, 4.25rem);   /* 38px at 390, 68px at 1440 */
  --fs-h2: clamp(1.75rem, 1.3rem + 1.6vw, 2.75rem);     /* 28px to 44px */
  --fs-h3: 1.375rem;

  --s1: 0.5rem;
  --s2: 1rem;
  --s3: 1.5rem;
  --s4: 2.5rem;
  --s5: 4rem;
  --section: clamp(3.5rem, 2rem + 5vw, 7rem);

  --w-page: 1200px;
  --gutter: clamp(1rem, 0.5rem + 2vw, 2rem);
  --header-h: 64px;

  --radius: 6px;
  --ease-out: cubic-bezier(.2, .7, .2, 1);
}

*, *::before, *::after { box-sizing: border-box; }

html {
  scroll-padding-top: calc(var(--header-h) + 8px);
  -webkit-text-size-adjust: 100%;
}

@media (prefers-reduced-motion: no-preference) {
  html { scroll-behavior: smooth; }
}

body {
  margin: 0;
  font-family: var(--text);
  font-size: var(--fs-body);
  line-height: 1.55;
  color: var(--ink);
  background: var(--ground);
  -webkit-font-smoothing: antialiased;
  overflow-wrap: break-word;
}

img { max-width: 100%; display: block; }
a { color: inherit; }
p { margin: 0 0 var(--s2); }
h1, h2, h3 { font-family: var(--display); font-weight: 700; margin: 0; overflow-wrap: break-word; }
h1 { font-size: var(--fs-h1); line-height: 1.04; letter-spacing: -0.015em; text-wrap: balance; }
h2 { font-size: var(--fs-h2); line-height: 1.12; letter-spacing: -0.01em; text-wrap: balance; }
h3 { font-size: var(--fs-h3); line-height: 1.25; }
.mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }

.wrap {
  width: 100%;
  max-width: var(--w-page);
  margin: 0 auto;
  padding-left: var(--gutter);
  padding-right: var(--gutter);
}

